<?php
function h($t,$level=2,$c=''){return '<!-- wp:heading '.wp_json_encode(['level'=>$level,'className'=>$c]).' --><h'.$level.' class="wp-block-heading'.($c?' '.esc_attr($c):'').'">'.$t.'</h'.$level.'><!-- /wp:heading -->';}
function p($t,$c=''){return '<!-- wp:paragraph '.wp_json_encode(['className'=>$c]).' --><p'.($c?' class="'.esc_attr($c).'"':'').'>'.$t.'</p><!-- /wp:paragraph -->';}
function g($x,$c){return '<!-- wp:group '.wp_json_encode(['className'=>$c,'layout'=>['type'=>'default']]).' --><div class="wp-block-group '.esc_attr($c).'">'.$x.'</div><!-- /wp:group -->';}
function image($key){$id=$GLOBALS['media'][$key];return '<!-- wp:image '.wp_json_encode(['id'=>$id,'sizeSlug'=>'full','linkDestination'=>'none']).' --><figure class="wp-block-image size-full"><img src="'.esc_url(wp_get_attachment_image_url($id,'full')).'" alt="'.esc_attr(get_post_meta($id,'_wp_attachment_image_alt',true)).'" class="wp-image-'.$id.'"/></figure><!-- /wp:image -->';}
function btn($t,$path){return '<!-- wp:buttons --><div class="wp-block-buttons"><!-- wp:button --><div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="'.esc_url(home_url('/'.trim($path,'/').'/')).'">'.$t.' →</a></div><!-- /wp:button --></div><!-- /wp:buttons -->';}
function dynamic($type,$attrs=[]){return '<!-- wp:'.$GLOBALS['block_prefix'].'/'.$type.($attrs?' '.wp_json_encode($attrs):'').' /-->';}
function page($slug,$title,$intro,$content){$prefix=$GLOBALS['css_prefix'];$banner=g(p($GLOBALS['brand'],$prefix.'-eyebrow').h($title,1).p($intro),$prefix.'-page-banner');return wp_insert_post(['post_author'=>1,'post_type'=>'page','post_status'=>'publish','post_title'=>$title,'post_name'=>$slug,'post_content'=>$banner.$content]);}
function record($type,$title,$copy,$img,$fields=[]){$id=wp_insert_post(['post_author'=>1,'post_type'=>$type,'post_status'=>'publish','post_title'=>$title,'post_content'=>$copy,'post_excerpt'=>$fields['summary']??'']);if($img)set_post_thumbnail($id,$GLOBALS['media'][$img]);foreach($fields as$k=>$v)update_field('field_'.$type.'_'.$k,$v,$id);return$id;}
function import_media($items){require_once ABSPATH.'wp-admin/includes/image.php';require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';$m=[];foreach($items as$key=>$alt){$tmp=wp_tempnam($key.'.jpg');copy(get_stylesheet_directory().'/assets/'.$key.'.jpg',$tmp);$id=media_handle_sideload(['name'=>$key.'.jpg','tmp_name'=>$tmp],0,$alt);if(is_wp_error($id))throw new Exception($id->get_error_message());update_post_meta($id,'_wp_attachment_image_alt',$alt);$m[$key]=$id;}$GLOBALS['media']=$m;return$m;}
